from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    visited = [[False] * n for _ in range(n)]
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    def dfs(x, y, path, steps):
        if k == steps:
            return path
        visited[x][y] = True
        for dx, dy in directions:
            nx, ny = (x + dx, y + dy)
            if 0 <= nx < n and 0 <= ny < n and (not visited[nx][ny]):
                result = dfs(nx, ny, path + [grid[nx][ny]], steps + 1)
                if result:
                    return result
        visited[x][y] = False
        return None
    min_path = []
    for i in range(n):
        for j in range(n):
            result = dfs(i, j, [grid[i][j]], 1)
            if result:
                min_path = result
                break
        if min_path:
            break
    return min_path

