def match_parens(lst):
    """
    Check if concatenating two strings from the given list can form a balanced string of parentheses.

    Args:
    lst (list): A list containing two strings consisting only of '(' and ')'.

    Returns:
    str: 'Yes' if a balanced string can be formed, 'No' otherwise.
    """

    def count_parentheses(s):
        balance = 0
        for char in s:
            if '(' == char:
                balance = balance + 1
            else:
                balance = balance - 1
            if 0 > balance:
                return False
        return 0 == balance
    for i in range(len(lst)):
        if count_parentheses(lst[i]) and count_parentheses(lst[(i + 1) % len(lst)]):
            return 'Yes'
    return 'No'

