def maxAverageOfPath(matrix):
    n = len(matrix)
    dp = [[0] * n for _ in range(n)]
    for i in range(1, n):
        dp[0][i] = dp[0][i - 1] + matrix[0][i]
    for j in range(1, n):
        dp[j][0] = dp[j - 1][0] + matrix[j][0]
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + matrix[i][j]
    max_avg = float('-inf')
    for i in range(n):
        for j in range(n):
            avg = dp[i][j] / (i + 1) * (j + 1)
