    gap = n // 2
    while 0 < gap:
        for i in range(gap, n):
            temp = arr[i]
            j = i - gap
            while 0 <= j and arr[j] > temp:
                arr[j + gap] = arr[j]
                j = j - gap
            arr[j + gap] = temp
        gap = gap // 2
    return arr

