    shrink_factor = 1.3
    while 1 < gap or any((arr[i + 1] < arr[i] for i in range(len(arr) - 1))):
        gap = int(gap / shrink_factor)
        if 1 > gap:
            gap = 1
        for i in range(len(arr) - gap):
            if arr[i + gap] < arr[i]:
                arr[i], arr[i + gap] = (arr[i + gap], arr[i])
